// 開発者向けデータ検査。児童向け画面には表示しません。
function validateEraQuestions() {
  const eraIds = new Set(HISTORY_ERAS.map(era => era.id));
  const questionTexts = new Set();
  const counts = Object.fromEntries(HISTORY_ERAS.map(era => [era.id, 0]));
  const answerDistribution = [0, 0, 0, 0];
  const errors = [];
  ERA_QUESTIONS.forEach((question, index) => {
    if (!eraIds.has(question.eraId)) errors.push(`${index}: 未登録の eraId`);
    else counts[question.eraId]++;
    if (!Array.isArray(question.choices) || question.choices.length !== 4) errors.push(`${index}: 選択肢が4つではありません`);
    if (!Number.isInteger(question.answer) || question.answer < 0 || question.answer > 3) errors.push(`${index}: answer が範囲外です`);
    else answerDistribution[question.answer]++;
    if (questionTexts.has(question.q)) errors.push(`${index}: 問題文が重複しています`);
    questionTexts.add(question.q);
    if (!question.category) errors.push(`${index}: category がありません`);
    if (!question.explanation) errors.push(`${index}: explanation がありません`);
  });
  HISTORY_ERAS.forEach(era => { if (counts[era.id] < 15) errors.push(`${era.id}: 15問未満です`); });
  return {total: ERA_QUESTIONS.length, counts, answerDistribution, errors};
}
